import { render } from '@testing-library/react';
import React from 'react';

import {
    DeviceVerificationStatusCard,
} from '../../../../../src/components/views/settings/devices/DeviceVerificationStatusCard';
import { DeviceWithVerification } from '../../../../../src/components/views/settings/devices/types';

describe('<DeviceVerificationStatusCard />', () => {
    it.each([
        [true, 'Verified', 'Verified session', 'This session is ready for secure messaging.'],
        [false, 'Unverified', 'Unverified session',
            'Verify or sign out from this session for best security and reliability.'],
        [null, 'Unverified', 'Unverified session',
            'Verify or sign out from this session for best security and reliability.'],
        [undefined, 'Unverified', 'Unverified session',
            'Verify or sign out from this session for best security and reliability.'],
    ])('renders the status for isVerified=%s', (isVerified, variation, heading, description) => {
        const device = { device_id: 'my-device', isVerified } as DeviceWithVerification;
        const { container, getByText } = render(<DeviceVerificationStatusCard device={device} />);

        expect(container.querySelector('.mx_DeviceSecurityCard_icon').classList.contains(variation)).toBe(true);
        expect(getByText(heading)).toBeTruthy();
        expect(getByText(description)).toBeTruthy();
    });
});
